const groupNames=['Communications','Public Works','Transit','Recreation','Customer Service','IT'];
const names=['Avery Morgan','Maya Chen','Noah Grant','Emma Roy','Liam Brooks','Sofia Patel','Oliver Reed','Chloe Martin','Ethan Ross','Amelia King','Lucas Bell','Isla Moore','Mason Clark','Harper Wood','Logan Scott','Ella Davis','Jacob Hall','Grace Wilson','Leo Adams','Zoe Carter','Henry Young','Lily Green','Owen Baker','Aria Walker','Jack Turner','Nora Hill','Finn Lewis','Ruby Allen','Theo Wright','Mila Evans'];
const seedGroups={users:names.map((name,i)=>({name,email:name.toLowerCase().replace(' ','.')+'@harbourview.example',group:groupNames[i%6],role:i===0?'Administrator':['Viewer','Editor','Responder','Approver','Analyst'][i%5]})),channels:Array.from({length:18},(_,i)=>({name:'Harbourview '+groupNames[i%6]+(i>5?' '+(Math.floor(i/6)+1):''),network:i<8?'Facebook':i<10?'Instagram':i<16?'Bluesky':i===16?'LinkedIn':'YouTube',group:groupNames[i%6]}))};
let groupData;try{groupData=JSON.parse(localStorage.getItem('ngyn-groups-v1'))||seedGroups}catch{groupData=seedGroups}
let activeGroup=groupNames[0],activeTab='users';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function installGroups(){if(document.querySelector('#groups-nav'))return;const b=document.createElement('button');b.id='groups-nav';b.innerHTML='<span class="ico">♧</span>Groups';document.querySelector('.nav').append(b);b.onclick=showGroups}
function showGroups(){document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));document.querySelector('#groups-nav').classList.add('active');document.querySelector('.crumb strong').textContent='Groups';document.querySelector('#main').innerHTML=`<div class="page-head groups-heading"><div><div class="eyebrow">WORKSPACE / GROUPS</div><h2>Groups</h2><p>Bring your people and social channels together.</p></div></div><div class="groups-layout"><aside class="group-picker"><div class="eyebrow">DEPARTMENTS</div>${groupNames.map(g=>`<button data-group="${g}" class="${g===activeGroup?'selected':''}">${g}<span>${groupData.users.filter(u=>u.group===g).length}</span></button>`).join('')}<p>Each group has its own people and channels.</p></aside><section class="group-panel"><div class="group-summary"><div class="group-initial">${activeGroup[0]}</div><div><h3>${activeGroup}</h3><p>Manage access and accounts for this department.</p></div><span class="badge ok">Demo group</span></div><div class="group-tabs">${['users','channels'].map(t=>`<button data-tab="${t}" class="${activeTab===t?'active':''}">${t==='users'?'Users':'Social channels'} <span>${groupData[t].filter(x=>x.group===activeGroup).length}</span></button>`).join('')}</div><div class="group-list-head"><div><h3>${activeTab==='users'?'People in this group':'Social channels'}</h3><p>${activeTab==='users'?'Assign a simple role to each member.':'The social accounts this group works with.'}</p></div><button class="btn primary" id="add-record">＋ ${activeTab==='users'?'Add user':'Add social channel'}</button></div><div class="group-search"><input id="record-search" aria-label="Search records" placeholder="${activeTab==='users'?'Search name or email…':'Search channels…'}"></div><div id="records"></div><div class="group-note">${activeTab==='users'?'Fictional demo users. No invitation emails are sent.':'Simulated accounts. No real social connections or API calls.'}</div></section></div>`;document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{activeGroup=b.dataset.group;showGroups()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;showGroups()});document.querySelector('#add-record').onclick=addGroupRecord;document.querySelector('#record-search').oninput=e=>renderRecords(e.target.value);renderRecords()}
function renderRecords(q=''){const users=activeTab==='users';const records=groupData[activeTab].filter(x=>x.group===activeGroup&&JSON.stringify(x).toLowerCase().includes(q.toLowerCase()));document.querySelector('#records').innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>${users?'Name':'Channel'}</th><th>${users?'Role':'Network'}</th><th>Status</th></tr></thead><tbody>${records.map(x=>`<tr><td><div class="person"><div class="avatar">${safe(x.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><div><strong>${safe(x.name)}</strong><small>${safe(users?x.email:'Fictional social account')}</small></div></div></td><td>${safe(users?x.role:x.network)}</td><td><span class="badge ok">${users?'Demo user':'Simulated'}</span></td></tr>`).join('')||'<tr><td colspan="3">No matches. Try another search.</td></tr>'}</tbody></table></div>`}
function addGroupRecord(){const users=activeTab==='users';modal(`<form id="record-form"><div class="modal-head"><div><div class="eyebrow">${activeGroup.toUpperCase()}</div><h2>${users?'Add user':'Add social channel'}</h2></div><button type="button" data-close aria-label="Close dialog">×</button></div><p class="form-description">${users?'Add a fictional staff member. No invitation email will be sent.':'Create a simulated account. Real connection setup will come later.'}</p>${users?'':`<div class="field"><label for="record-network">Social network</label><select id="record-network">${['Facebook','Instagram','Bluesky','LinkedIn','YouTube'].map(n=>`<option>${n}</option>`).join('')}</select></div>`}<div class="field"><label for="record-name">${users?'Full name':'Account name'}</label><input id="record-name" required maxlength="100" placeholder="${users?'e.g. Alex Taylor':'e.g. Harbourview Community Updates'}" autocomplete="off"></div>${users?'<div class="field"><label for="record-email">Demo email address</label><input id="record-email" type="email" required placeholder="alex.taylor@harbourview.example" autocomplete="off"><small>Use a fictional address in this demo.</small></div><div class="field"><label for="record-role">Role in this group</label><select id="record-role"><option>Viewer</option><option>Editor</option><option>Responder</option><option>Approver</option><option>Analyst</option></select><small id="role-description">Can view group content. Cannot edit, approve or publish.</small></div>':'<div class="group-note">No password or access token needed. Production permissions and capabilities remain unverified.</div>'}<p id="record-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">${users?'Add demo user':'Add demo channel'}</button></div></form>`);const box=document.querySelector('.modal-box');box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label',users?'Add user':'Add social channel');document.querySelector('#record-name').focus();if(users)document.querySelector('#record-role').onchange=e=>document.querySelector('#role-description').textContent=({Viewer:'Can view group content. Cannot edit, approve or publish.',Editor:'Can create drafts and submit them for approval.',Responder:'Can manage inquiries and draft replies.',Approver:'Can review and approve group content.',Analyst:'Can view analytics and prepare reports.'})[e.target.value];document.querySelector('#record-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#record-name').value.trim();if(!name){document.querySelector('#record-error').textContent='Enter a name.';return}const record={name,group:activeGroup};if(users){record.email=document.querySelector('#record-email').value.trim().toLowerCase();record.role=document.querySelector('#record-role').value;if(groupData.users.some(x=>x.group===activeGroup&&x.email===record.email)){document.querySelector('#record-error').textContent='This email already belongs to a user in this group.';return}}else{record.network=document.querySelector('#record-network').value;if(groupData.channels.some(x=>x.name.toLowerCase()===name.toLowerCase()&&x.network===record.network)){document.querySelector('#record-error').textContent='This demo channel already exists.';return}}groupData[activeTab].push(record);localStorage.setItem('ngyn-groups-v1',JSON.stringify(groupData));close();showGroups();toast(users?'Demo user added. No invitation sent.':'Demo channel added. No real account connected.')}}
document.addEventListener('click',e=>{if(e.target.closest('[data-page="overview"]')){e.preventDefault();e.stopImmediatePropagation();render();refine();installGroups()}},true);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});installGroups();
